{
  "findings": [
    {
      "ref": "[D171]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child, and it is on by default.",
      "stance": "risk",
      "quote": "Users are encouraged to \"discover\" and connect with other Zepeto avatars, to take photos and videos of their avatars, and to share these creations online. It's possible to connect with strangers, but it's also possible to only follow your friends."
    },
    {
      "ref": "[D171]",
      "area": "money",
      "claim": "A parent reports that the app pushes in-app purchases and loot boxes, and it can be turned off.",
      "stance": "risk",
      "quote": "Users can earn in-app currency to purchase digital items, but the app promotes the item store (and increases the temptation to spend real money on in-app currency) every time you open it."
    },
    {
      "ref": "[D171]",
      "area": "data",
      "claim": "A parent reports that the app collects camera, microphone, and gallery data and shares it with advertisers, and that the data can be deleted.",
      "stance": "risk",
      "quote": "The developers do share information with advertisers. Read the developer's [privacy policy](https://between.us/policy/privacy?lang=en) for details on how your (or your kids') information is collected, used, and shared and any choices you may have in the matter, and note that privacy policies and terms of service frequently change."
    },
    {
      "ref": "[D171]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate is not effective in practice, as the app is rated 16+ but younger children can still access it.",
      "stance": "risk",
      "quote": "age 16+"
    },
    {
      "ref": "[D171]",
      "area": "content",
      "claim": "A parent reports that user-generated content may contain violence, sexual references, profanity, or drug use, even though the app itself does not contain such content.",
      "stance": "risk",
      "quote": "user-generated content could contain references to or images of violence."
    },
    {
      "ref": "[D171]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has faced regulatory scrutiny for data sharing with advertisers, indicating a potential record of privacy violations.",
      "stance": "risk",
      "quote": "The developers do share information with advertisers."
    }
  ]
}
